import type { EncounterCommand } from './events';
import { gridDistance } from './grid';
import type { CombatantId } from './values';
import type { VisibleEncounterState } from './visibility';
import type { DmVisibleEncounterState } from './visibility';
import type { DecisionProgram } from '../vtt/dm-bridge/round-plan-contract';
import { canonicalJson } from '../commands/canonical-json';
import { coverTierBetweenObjects } from './encounter';

export interface LegalActionSummary {
  readonly actions: readonly EncounterCommand[];
}

export type ControllerRequest =
  | {
      readonly kind: 'turn';
      readonly requestId: string;
      readonly encounterRevision: number;
      readonly actorId: CombatantId;
      readonly visibleState: VisibleEncounterState;
      readonly legalActions: LegalActionSummary;
    }
  | {
      readonly kind: 'reaction';
      readonly requestId: string;
      readonly encounterRevision: number;
      readonly actorId: CombatantId;
      readonly moverId: CombatantId;
      readonly visibleState: VisibleEncounterState;
      readonly legalActions: LegalActionSummary;
    };

export interface ControllerDecision {
  readonly requestId: string;
  readonly encounterRevision: number;
  readonly action: EncounterCommand;
}

export interface Controller {
  readonly controllerKind?: ControllerKind;
  choose(
    request: ControllerRequest,
    signal: AbortSignal,
  ): Promise<ControllerDecision>;
}

export class ControllerRequestCancelledError extends Error {
  override readonly name = 'ControllerRequestCancelledError' as const;
}

export class StaleControllerResponseError extends Error {
  override readonly name = 'StaleControllerResponseError' as const;
}

interface PendingHumanRequest {
  readonly request: ControllerRequest;
  readonly resolve: (decision: ControllerDecision) => void;
  readonly reject: (reason: Error) => void;
  readonly detachAbort: () => void;
}

export class HumanController implements Controller {
  #pending: PendingHumanRequest | null = null;

  pendingRequest(): ControllerRequest | null {
    return this.#pending?.request ?? null;
  }

  choose(
    request: ControllerRequest,
    signal: AbortSignal,
  ): Promise<ControllerDecision> {
    if (this.#pending !== null) {
      return Promise.reject(new Error('HumanController already has a pending request.'));
    }
    if (signal.aborted) {
      return Promise.reject(new ControllerRequestCancelledError('Controller request was cancelled.'));
    }
    return new Promise((resolve, reject) => {
      const cancel = () => {
        if (this.#pending?.request.requestId !== request.requestId) return;
        this.#pending = null;
        reject(new ControllerRequestCancelledError('Controller request was cancelled.'));
      };
      signal.addEventListener('abort', cancel, { once: true });
      this.#pending = {
        request,
        resolve,
        reject,
        detachAbort: () => signal.removeEventListener('abort', cancel),
      };
    });
  }

  submit(decision: ControllerDecision): void {
    const pending = this.#pending;
    if (
      pending === null ||
      decision.requestId !== pending.request.requestId ||
      decision.encounterRevision !== pending.request.encounterRevision
    ) {
      throw new StaleControllerResponseError('Human response does not match the pending request.');
    }
    this.#pending = null;
    pending.detachAbort();
    pending.resolve(decision);
  }
}

function commandKey(command: EncounterCommand): string {
  return canonicalJson(command);
}

function movementRemaining(
  request: ControllerRequest,
  actorId: CombatantId,
): number | null {
  if ('viewer' in request.visibleState) {
    return request.visibleState.combatants.find((candidate) => candidate.id === actorId)
      ?.turn.movement.remaining ?? null;
  }
  if ('ownedCombatants' in request.visibleState) {
    return request.visibleState.ownedCombatants.find((candidate) => candidate.id === actorId)
      ?.turn.movement.remaining ?? null;
  }
  return null;
}

function clipMovementCandidate(
  request: ControllerRequest,
  command: EncounterCommand,
): EncounterCommand | null {
  if (command.type !== 'move') return command;
  const actor = request.visibleState.combatants.find((candidate) => candidate.id === command.actor);
  const budget = movementRemaining(request, command.actor);
  if (actor === undefined || budget === null) return command;
  const path: Array<(typeof command.path)[number]> = [];
  let previous = actor.position;
  let spent = 0;
  for (const cell of command.path) {
    const cost = gridDistance(previous, cell);
    if (spent + cost > budget) break;
    path.push(cell);
    spent += cost;
    previous = cell;
  }
  return path.length === 0 ? null : { ...command, path };
}

export function isListedControllerAction(
  command: EncounterCommand,
  legalActions: LegalActionSummary,
): boolean {
  return legalActions.actions.some((candidate) => {
    if (commandKey(candidate) === commandKey(command)) return true;
    if (
      command.type !== 'move' || candidate.type !== 'move' ||
      command.actor !== candidate.actor || command.cause !== candidate.cause ||
      command.path.length === 0 || command.path.length >= candidate.path.length
    ) return false;
    return command.path.every((cell, index) => {
      const listed = candidate.path[index];
      return listed !== undefined && listed.column === cell.column && listed.row === cell.row;
    });
  });
}

function visibleHostile(
  request: ControllerRequest,
  actorKind: VisibleEncounterState['combatants'][number]['kind'],
  id: CombatantId,
) {
  const target = request.visibleState.combatants.find((candidate) => candidate.id === id);
  return target !== undefined && target.kind !== actorKind && target.life !== 'dead'
    ? target
    : null;
}

function isTacticalHealingSpell(spellId: string): boolean {
  return spellId === 'cure-wounds' || spellId === 'healing-word';
}

function isTacticalRangedSpell(spellId: string): boolean {
  return spellId === 'eldritch-blast' || spellId === 'ray-of-frost' || spellId === 'slow' ||
    spellId === 'spirit-guardians' || spellId === 'command';
}

const COVER_RANK = {
  none: 0,
  half: 1,
  three_quarters: 2,
  total: 3,
} as const;

function visibleAlly(
  request: ControllerRequest,
  actorKind: VisibleEncounterState['combatants'][number]['kind'],
  id: CombatantId,
) {
  const target = request.visibleState.combatants.find((candidate) => candidate.id === id);
  return target !== undefined && target.kind === actorKind && target.life !== 'dead'
    ? target
    : null;
}

function lastKnownHitPoints(
  request: ControllerRequest,
  id: CombatantId,
): { readonly current: number; readonly maximumKnown: number } | null {
  if ('viewer' in request.visibleState) {
    const target = request.visibleState.combatants.find((candidate) => candidate.id === id);
    return target === undefined
      ? null
      : { current: target.hitPoints, maximumKnown: target.rules.hitPointMaximum };
  }
  if ('ownedCombatants' in request.visibleState) {
    const owned = request.visibleState.ownedCombatants.find((candidate) => candidate.id === id);
    if (owned !== undefined) {
      return { current: owned.hitPoints, maximumKnown: owned.hitPointMaximum };
    }
  }
  const hitPointEvents: Array<{
    readonly hitPointsBefore: number;
    readonly hitPointsAfter: number;
  }> = [];
  for (const event of request.visibleState.recentEvents) {
    if (
      (event.type === 'damage_applied' || event.type === 'healing_applied') &&
      event.target === id
    ) hitPointEvents.push(event);
  }
  const latest = hitPointEvents.at(-1);
  if (latest === undefined) return null;
  return {
    current: latest.hitPointsAfter,
    maximumKnown: Math.max(...hitPointEvents.flatMap((event) => [
      event.hitPointsBefore,
      event.hitPointsAfter,
    ])),
  };
}

function healingPriority(
  request: ControllerRequest,
  target: VisibleEncounterState['combatants'][number],
): 0 | 1 | null {
  if (target.life === 'dying') return 0;
  const hitPoints = lastKnownHitPoints(request, target.id);
  return hitPoints !== null && hitPoints.current * 4 <= hitPoints.maximumKnown * 3 ? 1 : null;
}

function focusRank(
  request: ControllerRequest,
  actor: VisibleEncounterState['combatants'][number],
  target: VisibleEncounterState['combatants'][number],
): readonly [number, number] {
  return [
    lastKnownHitPoints(request, target.id)?.current ?? Number.POSITIVE_INFINITY,
    gridDistance(actor.position, target.position),
  ];
}

function usedRangedActionThisTurn(
  request: ControllerRequest,
  actor: VisibleEncounterState['combatants'][number],
): boolean {
  let lastTurnStart = -1;
  for (const [index, event] of request.visibleState.recentEvents.entries()) {
    if (event.type === 'turn_started' && event.combatant === actor.id) lastTurnStart = index;
  }
  return request.visibleState.recentEvents.slice(lastTurnStart + 1).some((event) => {
    if (event.type === 'attack_resolved' && event.actor === actor.id) {
      const target = visibleHostile(request, actor.kind, event.target);
      return target !== null && gridDistance(actor.position, target.position) > 5;
    }
    if (event.type === 'spell_cast' && event.caster === actor.id) {
      if (isTacticalRangedSpell(event.spellId)) return true;
      return event.targets.some((id) => {
        const target = visibleHostile(request, actor.kind, id);
        return target !== null && gridDistance(actor.position, target.position) > 5;
      });
    }
    return false;
  });
}

function playerCharacterAlgorithmRank(
  request: ControllerRequest,
  command: EncounterCommand,
  actor: VisibleEncounterState['combatants'][number],
): readonly [number, number, number, string] {
  const isWeaponMasteryDefender = request.legalActions.actions.some((action) =>
    action.type === 'attack' && action.weaponMastery !== undefined);
  const hasToppleTarget = request.legalActions.actions.some((action) =>
    action.type === 'attack' && action.weaponMastery?.property === 'Topple');
  if (command.type === 'drink_healing_potion') {
    const hitPoints = lastKnownHitPoints(request, actor.id);
    return [1, hitPoints?.current ?? 0, 0, commandKey(command)];
  }
  if (command.type === 'opportunity_attack') {
    const target = visibleHostile(request, actor.kind, command.target);
    if (target !== null) {
      const [hitPoints, distance] = focusRank(request, actor, target);
      return [0, hitPoints, distance, commandKey(command)];
    }
  }
  if (command.type === 'cast_spell') {
    if (command.spellId === 'revivify') return [0, -3, 0, commandKey(command)];
    if (command.spellId === 'bless') return [0, -1, 0, commandKey(command)];
    if (command.spellId === 'slow' || command.spellId === 'spirit-guardians') {
      return [0, -2, 0, commandKey(command)];
    }
    if (command.spellId === 'command') return [1, -1, 0, commandKey(command)];
    if (isTacticalHealingSpell(command.spellId)) {
      const ally = command.targets
        .map((id) => visibleAlly(request, actor.kind, id))
        .filter((candidate) => candidate !== null)
        .sort((left, right) => {
          const leftPriority = healingPriority(request, left) ?? Number.POSITIVE_INFINITY;
          const rightPriority = healingPriority(request, right) ?? Number.POSITIVE_INFINITY;
          return leftPriority - rightPriority || left.id.localeCompare(right.id);
        })[0];
      const priority = ally === undefined ? null : healingPriority(request, ally);
      if (ally !== undefined && priority !== null) {
        return [priority, lastKnownHitPoints(request, ally.id)?.current ?? 0, 0, commandKey(command)];
      }
      return [8, 0, 0, commandKey(command)];
    }
    const target = command.targets
      .map((id) => visibleHostile(request, actor.kind, id))
      .filter((candidate) => candidate !== null)
      .sort((left, right) => {
        const [leftHitPoints, leftDistance] = focusRank(request, actor, left);
        const [rightHitPoints, rightDistance] = focusRank(request, actor, right);
        return leftHitPoints - rightHitPoints || leftDistance - rightDistance ||
          left.id.localeCompare(right.id);
      })[0];
    if (target !== undefined) {
      const [hitPoints, distance] = focusRank(request, actor, target);
      return [2, hitPoints, distance, commandKey(command)];
    }
  }
  if (command.type === 'attack') {
    const target = visibleHostile(request, actor.kind, command.target);
    if (target !== null) {
      const [hitPoints, distance] = focusRank(request, actor, target);
      return command.weaponMastery?.property === 'Topple'
        ? [2, hitPoints, distance, commandKey(command)]
        : [3, hitPoints, distance, commandKey(command)];
    }
  }
  if (command.type === 'force_save') {
    const target = visibleHostile(request, actor.kind, command.target);
    if (target !== null) {
      const [hitPoints, distance] = focusRank(request, actor, target);
      return [3, hitPoints, distance, commandKey(command)];
    }
  }
  if (command.type === 'move') {
    const destination = command.path.at(-1) ?? actor.position;
    const nearest = Math.min(
      ...request.visibleState.combatants
        .filter((candidate) => candidate.kind !== actor.kind && candidate.life !== 'dead')
        .map((candidate) => gridDistance(destination, candidate.position)),
    );
    if (isWeaponMasteryDefender) {
      // The defender advances between the nearest hostile and the ranged
      // casters, preferring a legal Topple attack once melee is reached. The
      // grid has no occupied-cell path reservation, so nearest-hostile
      // interposition is the movement model's concrete body-block primitive.
      return hasToppleTarget ? [4, nearest, 0, commandKey(command)] : [2, nearest, 0, commandKey(command)];
    }
    if (usedRangedActionThisTurn(request, actor)) {
      const currentlyAdjacent = request.visibleState.combatants.some((candidate) =>
        candidate.kind !== actor.kind && candidate.life !== 'dead' &&
        gridDistance(actor.position, candidate.position) <= 5);
      const currentNearest = Math.min(
        ...request.visibleState.combatants
          .filter((candidate) => candidate.kind !== actor.kind && candidate.life !== 'dead')
          .map((candidate) => gridDistance(actor.position, candidate.position)),
      );
      const cover = Math.max(0, ...request.visibleState.combatants
        .filter((candidate) => candidate.kind !== actor.kind && candidate.life !== 'dead')
        .map((candidate) => COVER_RANK[coverTierBetweenObjects(
          request.visibleState.worldObjects,
          destination,
          candidate.position,
        )]));
      return currentlyAdjacent || nearest <= currentNearest
        ? [10, 0, 0, commandKey(command)]
        : [4, -nearest, -cover, commandKey(command)];
    }
    return [4, nearest, 0, commandKey(command)];
  }
  if (command.type === 'dash') return [5, 0, 0, commandKey(command)];
  if (command.type === 'decline_reaction') return [6, 0, 0, commandKey(command)];
  if (command.type === 'end_turn') return [9, 0, 0, commandKey(command)];
  return [8, 0, 0, commandKey(command)];
}

function algorithmRank(
  request: ControllerRequest,
  command: EncounterCommand,
): readonly [number, number, number, string] {
  const actor = request.visibleState.combatants.find(
    (candidate) => candidate.id === request.actorId,
  );
  if (actor?.kind === 'player_character') {
    return playerCharacterAlgorithmRank(request, command, actor);
  }
  const hostile = (id: CombatantId) => {
    const target = request.visibleState.combatants.find((candidate) => candidate.id === id);
    return actor !== undefined && target !== undefined && actor.kind !== target.kind;
  };
  if (command.type === 'opportunity_attack' && hostile(command.target)) {
    return [0, 0, 0, commandKey(command)];
  }
  if (command.type === 'attack' && hostile(command.target)) {
    const target = request.visibleState.combatants.find(
      (candidate) => candidate.id === command.target,
    );
    const distance =
      actor === undefined || target === undefined
        ? Number.POSITIVE_INFINITY
        : gridDistance(actor.position, target.position);
    return [1, distance, 0, commandKey(command)];
  }
  if (command.type === 'move') {
    const destination = command.path.at(-1) ?? actor?.position;
    const nearest = destination === undefined
      ? Number.POSITIVE_INFINITY
      : Math.min(
          ...request.visibleState.combatants
            .filter((candidate) => hostile(candidate.id))
            .map((candidate) => gridDistance(destination, candidate.position)),
        );
    return [2, nearest, 0, commandKey(command)];
  }
  if (command.type === 'decline_reaction') return [3, 0, 0, commandKey(command)];
  if (command.type === 'end_turn') return [5, 0, 0, commandKey(command)];
  return [4, 0, 0, commandKey(command)];
}

export class AlgorithmController implements Controller {
  /**
   * Enumerates the primitive turn programs considered by the algorithm controller.
   * Candidates are ranked by descending heuristic score, then by canonical JSON.
   * The canonical-JSON tie-break is the stable sort key captured by experiments,
   * so enumeration is independent of source-array or engine sort stability.
   */
  enumerateTurnPrograms(
    state: DmVisibleEncounterState,
    actorId: CombatantId,
    limitOrLegalActions: number | LegalActionSummary = 64,
    playerLimit = 64,
  ): readonly AlgorithmTurnCandidate[] {
    const limit = typeof limitOrLegalActions === 'number' ? limitOrLegalActions : playerLimit;
    if (!Number.isSafeInteger(limit) || limit < 1) {
      throw new RangeError('Algorithm turn candidate limit must be a positive integer.');
    }
    const actor = state.combatants.find((candidate) => candidate.id === actorId);
    if (actor === undefined || actor.life !== 'living') {
      throw new TypeError('Algorithm turn candidates require a living combatant in the DM projection.');
    }
    const enemies = state.combatants
      .filter((candidate) => candidate.kind !== actor.kind && candidate.life !== 'dead')
      .sort((left, right) => {
        const distance = gridDistance(actor.position, left.position) - gridDistance(actor.position, right.position);
        return distance || left.id.localeCompare(right.id);
      });
    const nearest = enemies[0];
    const candidates: { readonly program: DecisionProgram; readonly score: number }[] = [];
    if (actor.kind === 'player_character') {
      const legalActions = typeof limitOrLegalActions === 'number'
        ? null
        : limitOrLegalActions.actions;
      if (legalActions === null) {
        for (const enemy of enemies) {
          candidates.push({
            program: {
              kind: 'action',
              action: { kind: 'attack', target: { kind: 'combatant', combatantId: enemy.id } },
            },
            score: 1_000 - enemy.hitPoints,
          });
          candidates.push({
            program: {
              kind: 'action',
              action: { kind: 'force_save', target: { kind: 'combatant', combatantId: enemy.id } },
            },
            score: 990 - enemy.hitPoints,
          });
        }
        if (nearest !== undefined) {
          candidates.push({
            program: {
              kind: 'action',
              action: { kind: 'move_toward', target: { kind: 'combatant', combatantId: nearest.id } },
            },
            score: 50,
          });
        }
        candidates.push({
          program: { kind: 'action', action: { kind: 'use_action', action: 'dash' } },
          score: 40,
        });
      } else {
        for (const command of legalActions) {
          if (command.type === 'attack') {
            const target = enemies.find((enemy) => enemy.id === command.target);
            if (target === undefined) continue;
            candidates.push({
              program: {
                kind: 'action',
                action: {
                  kind: 'attack',
                  target: { kind: 'combatant', combatantId: target.id },
                  ...(command.attackId === undefined ? {} : { attackId: command.attackId }),
                },
              },
              score: 1_000 - target.hitPoints,
            });
          } else if (command.type === 'force_save') {
            const target = enemies.find((enemy) => enemy.id === command.target);
            if (target === undefined) continue;
            candidates.push({
              program: {
                kind: 'action',
                action: { kind: 'force_save', target: { kind: 'combatant', combatantId: target.id } },
              },
              score: 990 - target.hitPoints,
            });
          } else if (command.type === 'cast_spell') {
            for (const targetId of new Set(command.targets)) {
              const target = enemies.find((enemy) => enemy.id === targetId);
              if (target === undefined) continue;
              candidates.push({
                program: {
                  kind: 'action',
                  action: {
                    kind: 'cast_spell',
                    spellId: command.spellId,
                    target: { kind: 'combatant', combatantId: target.id },
                  },
                },
                score: 1_100 - target.hitPoints,
              });
            }
          }
        }
        if (
          nearest !== undefined &&
          legalActions.some((command) => command.type === 'move')
        ) {
          candidates.push({
            program: {
              kind: 'action',
              action: { kind: 'move_toward', target: { kind: 'combatant', combatantId: nearest.id } },
            },
            score: 50,
          });
        }
        if (legalActions.some((command) => command.type === 'dash')) {
          candidates.push({
            program: { kind: 'action', action: { kind: 'use_action', action: 'dash' } },
            score: 40,
          });
        }
      }
      candidates.push({
        program: { kind: 'action', action: { kind: 'use_action', action: 'end_turn' } },
        score: 0,
      });
      const byProgram = new Map<string, AlgorithmTurnCandidate>();
      for (const candidate of candidates) {
        const stableSortKey = canonicalJson(candidate.program);
        const existing = byProgram.get(stableSortKey);
        if (existing === undefined || candidate.score > existing.score) {
          byProgram.set(stableSortKey, { ...candidate, stableSortKey });
        }
      }
      return [...byProgram.values()]
        .sort((left, right) =>
          right.score - left.score || left.stableSortKey.localeCompare(right.stableSortKey))
        .slice(0, limit);
    }
    for (const enemy of enemies) {
      const distance = gridDistance(actor.position, enemy.position);
      candidates.push({
        program: {
          kind: 'action',
          action: { kind: 'attack', target: { kind: 'combatant', combatantId: enemy.id } },
        },
        score: 100 - distance,
      });
      candidates.push({
        program: {
          kind: 'action',
          action: { kind: 'force_save', target: { kind: 'combatant', combatantId: enemy.id } },
        },
        score: 96 - distance,
      });
    }
    if (nearest !== undefined) {
      candidates.push({
        program: {
          kind: 'action',
          action: { kind: 'move_toward', target: { kind: 'combatant', combatantId: nearest.id } },
        },
        score: 50 - gridDistance(actor.position, nearest.position),
      });
    }
    if (candidates.length === 0) {
      candidates.push({
        program: { kind: 'action', action: { kind: 'use_action', action: 'dodge' } },
        score: 0,
      });
    }
    candidates.push({
      program: { kind: 'action', action: { kind: 'use_action', action: 'end_turn' } },
      score: 0,
    });
    return candidates
      .map((candidate) => ({
        ...candidate,
        stableSortKey: canonicalJson(candidate.program),
      }))
      .sort((left, right) =>
        right.score - left.score || left.stableSortKey.localeCompare(right.stableSortKey))
      .slice(0, limit);
  }

  proposeRoundProgram(
    state: DmVisibleEncounterState,
    actorId: CombatantId,
  ): AlgorithmRoundProposal {
    const ranked = this.enumerateTurnPrograms(state, actorId, 20);
    const top = ranked[0]?.score ?? 0;
    const second = ranked[1]?.score ?? top;
    return {
      program: {
        kind: 'priority',
        choices: ranked.map((candidate) => candidate.program),
      },
      topActionGapPercent: top === 0 ? 0 : Math.abs(top - second) * 100 / Math.abs(top),
    };
  }

  async choose(
    request: ControllerRequest,
    signal: AbortSignal,
  ): Promise<ControllerDecision> {
    if (signal.aborted) {
      throw new ControllerRequestCancelledError('Controller request was cancelled.');
    }
    const action = request.legalActions.actions
      .map((candidate) => clipMovementCandidate(request, candidate))
      .filter((candidate) => candidate !== null)
      .sort((left, right) => {
        const leftRank = algorithmRank(request, left);
        const rightRank = algorithmRank(request, right);
        return (
          leftRank[0] - rightRank[0] ||
          leftRank[1] - rightRank[1] ||
          leftRank[2] - rightRank[2] ||
          leftRank[3].localeCompare(rightRank[3])
        );
      })[0];
    if (action === undefined) throw new Error('Controller request has no legal actions.');
    return {
      requestId: request.requestId,
      encounterRevision: request.encounterRevision,
      action,
    };
  }
}

export interface AlgorithmRoundProposal {
  readonly program: DecisionProgram;
  readonly topActionGapPercent: number;
}

export interface AlgorithmTurnCandidate {
  readonly program: DecisionProgram;
  readonly score: number;
  readonly stableSortKey: string;
}

export interface AgentControllerRequest {
  readonly protocolVersion: 1;
  readonly requestId: string;
  readonly encounterRevision: number;
  readonly actorId: CombatantId;
  readonly visibleBoard: VisibleEncounterState;
  readonly legalActions: LegalActionSummary;
}

export interface AgentControllerResponse {
  readonly protocolVersion: 1;
  readonly requestId: string;
  readonly encounterRevision: number;
  readonly action: EncounterCommand;
}

export interface AgentExchange {
  exchange(request: AgentControllerRequest, signal: AbortSignal): Promise<unknown>;
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

const AGENT_COMMAND_TYPES = {
  roll_initiative: true,
  move: true,
  attack: true,
  opportunity_attack: true,
  decline_reaction: true,
  force_save: true,
  dash: true,
  disengage: true,
  dodge: true,
  spend_bonus_action: true,
  spend_reaction: true,
  activate_action_surge: true,
  heal: true,
  apply_effect: true,
  end_concentration: true,
  end_turn: true,
} as const satisfies Partial<Record<EncounterCommand['type'], true>>;

export type AgentEncounterCommandType = keyof typeof AGENT_COMMAND_TYPES;

export function isAgentEncounterCommandType(
  value: unknown,
): value is AgentEncounterCommandType {
  return typeof value === 'string' && Object.hasOwn(AGENT_COMMAND_TYPES, value);
}

function decodeEncounterCommand(value: unknown): EncounterCommand {
  if (!isRecord(value) || typeof value.type !== 'string') {
    throw new TypeError('Agent response action must be an encounter command object.');
  }
  if (!isAgentEncounterCommandType(value.type)) {
    throw new TypeError('Agent response action has an unknown command type.');
  }
  return value as unknown as EncounterCommand;
}

export function decodeAgentControllerResponse(
  value: unknown,
): AgentControllerResponse {
  if (
    !isRecord(value) ||
    value.protocolVersion !== 1 ||
    typeof value.requestId !== 'string' ||
    !Number.isSafeInteger(value.encounterRevision)
  ) {
    throw new TypeError('Malformed agent controller response envelope.');
  }
  return {
    protocolVersion: 1,
    requestId: value.requestId,
    encounterRevision: value.encounterRevision as number,
    action: decodeEncounterCommand(value.action),
  };
}

export class AgentController implements Controller {
  constructor(private readonly exchange: AgentExchange) {}

  async choose(
    request: ControllerRequest,
    signal: AbortSignal,
  ): Promise<ControllerDecision> {
    const response = decodeAgentControllerResponse(
      await this.exchange.exchange(
        {
          protocolVersion: 1,
          requestId: request.requestId,
          encounterRevision: request.encounterRevision,
          actorId: request.actorId,
          visibleBoard: request.visibleState,
          legalActions: request.legalActions,
        },
        signal,
      ),
    );
    if (
      response.requestId !== request.requestId ||
      response.encounterRevision !== request.encounterRevision
    ) {
      throw new StaleControllerResponseError('Agent response is stale.');
    }
    return response;
  }
}

export interface ControllerAssignment {
  readonly combatantId: CombatantId;
  readonly controller: Controller;
  readonly controllerId?: string;
}

interface RegistryEntry {
  readonly controller: Controller;
  readonly generation: number;
  readonly controllerId: string;
  readonly kind: ControllerKind;
}

export type ControllerKind = 'human' | 'algorithm' | 'agent' | 'custom';

export interface ControllerIdentity {
  readonly combatantId: CombatantId;
  readonly controllerId: string;
  readonly kind: ControllerKind;
  readonly generation: number;
}

function controllerKind(controller: Controller): ControllerKind {
  if (controller.controllerKind !== undefined) return controller.controllerKind;
  if (controller instanceof HumanController) return 'human';
  if (controller instanceof AlgorithmController) return 'algorithm';
  if (controller instanceof AgentController) return 'agent';
  return 'custom';
}

function defaultControllerId(
  combatantId: CombatantId,
  kind: ControllerKind,
  generation: number,
): string {
  return `${combatantId}:${kind}:${generation}`;
}

export class ControllerRegistry {
  readonly #entries = new Map<CombatantId, RegistryEntry>();
  readonly #replaceListeners = new Set<(id: CombatantId) => void>();

  constructor(assignments: readonly ControllerAssignment[]) {
    for (const assignment of assignments) {
      if (this.#entries.has(assignment.combatantId)) {
        throw new Error(`Duplicate controller assignment for ${assignment.combatantId}.`);
      }
      this.#entries.set(assignment.combatantId, {
        controller: assignment.controller,
        generation: 0,
        controllerId:
          assignment.controllerId ??
          defaultControllerId(
            assignment.combatantId,
            controllerKind(assignment.controller),
            0,
          ),
        kind: controllerKind(assignment.controller),
      });
    }
  }

  controllerFor(combatantId: CombatantId): Controller {
    const entry = this.#entries.get(combatantId);
    if (entry === undefined) throw new Error(`No controller assigned to ${combatantId}.`);
    return entry.controller;
  }

  generationFor(combatantId: CombatantId): number {
    const entry = this.#entries.get(combatantId);
    if (entry === undefined) throw new Error(`No controller assigned to ${combatantId}.`);
    return entry.generation;
  }

  kindFor(combatantId: CombatantId): ControllerKind {
    const entry = this.#entries.get(combatantId);
    if (entry === undefined) throw new Error(`No controller assigned to ${combatantId}.`);
    return entry.kind;
  }

  identities(): readonly ControllerIdentity[] {
    return [...this.#entries.entries()]
      .map(([combatantId, entry]) => ({
        combatantId,
        controllerId: entry.controllerId,
        kind: entry.kind,
        generation: entry.generation,
      }))
      .sort((left, right) => left.combatantId.localeCompare(right.combatantId));
  }

  /** Assigns a newly summoned combatant to the summoner's exact controller seam. */
  assignFrom(combatantId: CombatantId, source: CombatantId): void {
    if (this.#entries.has(combatantId)) {
      throw new Error(`Controller already assigned to ${combatantId}.`);
    }
    const sourceEntry = this.#entries.get(source);
    if (sourceEntry === undefined) throw new Error(`No controller assigned to ${source}.`);
    this.#entries.set(combatantId, {
      controller: sourceEntry.controller,
      generation: sourceEntry.generation,
      controllerId: sourceEntry.controllerId,
      kind: sourceEntry.kind,
    });
  }

  remove(combatantId: CombatantId): void {
    if (!this.#entries.delete(combatantId)) {
      throw new Error(`No controller assigned to ${combatantId}.`);
    }
  }

  replace(
    combatantId: CombatantId,
    controller: Controller,
    controllerId?: string,
  ): void {
    const current = this.#entries.get(combatantId);
    if (current === undefined) throw new Error(`No controller assigned to ${combatantId}.`);
    const generation = current.generation + 1;
    const kind = controllerKind(controller);
    this.#entries.set(combatantId, {
      controller,
      generation,
      controllerId:
        controllerId ?? defaultControllerId(combatantId, kind, generation),
      kind,
    });
    for (const listener of this.#replaceListeners) listener(combatantId);
  }

  onReplace(listener: (id: CombatantId) => void): () => void {
    this.#replaceListeners.add(listener);
    return () => this.#replaceListeners.delete(listener);
  }
}

export type ReactionPolicyDecision = 'use' | 'decline' | 'prompt';

export type StandingReactionPolicy =
  | { readonly opportunityAttack: 'use' }
  | { readonly opportunityAttack: 'decline' };

/** An absent standing policy is ambiguity and must reach the human prompt. */
export function evaluateOpportunityAttackPolicy(
  policy: StandingReactionPolicy | null,
): ReactionPolicyDecision {
  if (policy === null) return 'prompt';
  switch (policy.opportunityAttack) {
    case 'use':
      return 'use';
    case 'decline':
      return 'decline';
  }
}

