export type PartyPackRefusalReason =
  | 'invalid_json'
  | 'invalid_structure'
  | 'unknown_spell_id'
  | 'too_many_spellcasting_sources'
  | 'unsupported_effect_shape'
  | 'gaps_not_allowed'
  | 'no_mappable_members';

