  | {
      readonly kind: 'external_party_pack_refusal';
      readonly reason: Exclude<PartyPackRefusalReason, 'unsupported_effect_shape'>;
    }
  | {
      readonly kind: 'external_party_pack_refusal';
      readonly reason: 'unsupported_effect_shape';
      readonly unsupportedShape: string;
    };

export type PartyPackLoadResult =
  | {
      readonly status: 'loaded';
      readonly party: LoadedExternalPartyPack;
      readonly gaps: readonly GapReport[];
    }
  | {
      readonly status: 'refused';
      readonly refusal: PartyPackRefusal;
      readonly gaps: readonly GapReport[];
    };

export type LoadedPartySource =
  | { readonly kind: 'reference' }
  | {
      readonly kind: 'external-pack';
      readonly packFile: string;
      readonly result: PartyPackLoadResult;
    };

export async function loadPartySource(
  sourceValue: unknown,
  readPackFile: (packFile: string) => Promise<string>,
): Promise<LoadedPartySource> {
  const source = partySourceSchema.parse(sourceValue);
  if (source === 'reference') return { kind: 'reference' };
  return {
    kind: 'external-pack',
    packFile: source.packFile,
    result: loadExternalPartyPackBytes(await readPackFile(source.packFile)),
  };
}

type NonNullish<T> = Exclude<T, null | undefined>;
type NestedPaths<T> = T extends readonly (infer Entry)[]
  ? readonly [number] | readonly [number, ...NestedPaths<NonNullish<Entry>>]
  : T extends object
    ? {
        readonly [Key in Extract<keyof T, string>]:
          | readonly [Key]
          | readonly [Key, ...NestedPaths<NonNullish<T[Key]>>];
      }[Extract<keyof T, string>]
    : never;

export type PartyPackPath = readonly [] | NestedPaths<ExternalPartyPack>;

export type PartyPackExactFields<T> = Readonly<Record<Extract<keyof T, string>, true>>;
export type PartyPackExactFieldRecord<T, Candidate> =
  Candidate extends PartyPackExactFields<T>
    ? Exclude<keyof Candidate, keyof T> extends never
      ? Candidate
      : never
    : never;
type ExactFields<T> = PartyPackExactFields<T>;
type FieldRecord = Readonly<Record<string, true>>;

function pathFor<T>() {
  return <const Path extends NestedPaths<T>>(...parts: Path): Path => parts;
}

const partyPath = pathFor<ExternalPartyPack>();

function exactAbilityFields(): ExactFields<Record<Ability, number>> {
  return Object.fromEntries(abilities.map((ability) => [ability, true])) as ExactFields<
    Record<Ability, number>
  >;
}

