import { describe, expect, it } from 'vitest';
import {
  combatantConditions,
  createEncounter,
  reduceEncounter,
  type EncounterState,
} from '../../../src/combat/encounter';
import type { PersistentAreaInput, PersistentAreaMaterial } from '../../../src/combat/persistent-areas';
import {
  GREASE_MATERIAL,
  WEB_MATERIAL,
  persistentAreaContains,
} from '../../../src/combat/persistent-areas';
import { spellDefinition } from '../../../src/combat/spells/definitions';
import { feetPoint } from '../../../src/combat/templates';
import {
  damageType,
  dieSides,
  effectStackingIdentity,
  feet,
  type DamageType,
} from '../../../src/combat/values';
import { monsterProfile, placedToken, playerProfile } from '../combat/fixtures';

const NONFLAMMABLE_MATERIAL: PersistentAreaMaterial = {
  id: 'stone-dust',
  flammability: { kind: 'nonflammable' },
};

function faceOne(): number {
  return 0;
}

function setup(optionalRules: readonly 'flammable_grease'[] = []) {
  const owner = playerProfile('surface-owner', { initiativeBonus: 30, hitPoints: 30 });
  const fireDealer = playerProfile('surface-fire-dealer', { initiativeBonus: 20, hitPoints: 30 });
  const target = monsterProfile('surface-target', { initiativeBonus: 10, hitPoints: 30 });
  const state = reduceEncounter(createEncounter({
    config: { initiativeMode: 'per_combatant', optionalRules },
    bounds: { columns: 8, rows: 3 },
    combatants: [owner, fireDealer, target],
    tokens: [placedToken(owner, 0, 1), placedToken(fireDealer, 1, 1), placedToken(target, 3, 1)],
  }), { type: 'roll_initiative' }, faceOne).state;
  return { state, owner, fireDealer, target };
}

function webHooks(): PersistentAreaInput['hooks'] {
  return (['on_enter', 'on_start_of_turn_inside'] as const).map((hook) => ({
    hook,
    frequency: 'once_per_turn' as const,
    effect: {
      kind: 'save_gated' as const,
      ability: 'dexterity' as const,
      dc: 20,
      rollMode: 'normal' as const,
      onSuccess: 'none' as const,
      payload: {
        kind: 'effect' as const,
        payload: { kind: 'condition' as const, condition: 'Restrained' as const },
        lifetime: { kind: 'while_inside' as const },
      },
    },
  }));
}

function area(
  state: EncounterState,
  material: PersistentAreaMaterial,
  hooks: PersistentAreaInput['hooks'] = [],
): PersistentAreaInput {
  const owner = state.combatants[0]?.profile.id;
  const target = state.combatants[2]?.profile.id;
  if (owner === undefined || target === undefined) throw new Error('Surface fixture is incomplete.');
  return {
    owner,
    origin: { kind: 'fixed', point: feetPoint(15, 5) },
    shape: { kind: 'sphere', radius: feet(20) },
    duration: { kind: 'rounds', remaining: 10 },
    targetFilter: { kind: 'selected', combatants: [target] },
    difficultTerrain: true,
    material,
    hooks,
    movable: null,
  };
}

function createArea(
  state: EncounterState,
  input: PersistentAreaInput,
): EncounterState {
  return reduceEncounter(state, {
    type: 'create_persistent_area', actor: input.owner, area: input, cost: 'none',
  }, faceOne).state;
}

function advanceToFireDealer(
  state: EncounterState,
  owner: ReturnType<typeof playerProfile>,
): EncounterState {
  return reduceEncounter(state, { type: 'end_turn', actor: owner.id }, faceOne).state;
}

function dealDamage(
  state: EncounterState,
  actor: ReturnType<typeof playerProfile>,
  target: ReturnType<typeof monsterProfile>,
  type: DamageType,
): EncounterState {
  return reduceEncounter(state, {
    type: 'force_save', actor: actor.id, target: target.id,
    ability: 'dexterity', dc: 20, rollMode: 'normal', onSuccess: 'none', cost: 'none',
    damage: {
      terms: [{ type, dice: { count: 0, sides: dieSides(4), modifier: 1 } }],
      critical: false,
      responses: [],
    },
  }, faceOne).state;
}

function hitPoints(state: EncounterState, id: string): number {
  const subject = state.combatants.find((candidate) => candidate.profile.id === id);
  if (subject === undefined) throw new Error(`Missing combatant ${id}.`);
  return subject.hitPoints;
}

describe('D371.1 and D373.17 flammable persistent-area cells', () => {
  it('bundled Web is RAW-flammable while Grease is a default-off named optional rule', () => {
    const web = spellDefinition('web');
    const grease = spellDefinition('grease');
    expect(web?.operation).toMatchObject({
      kind: 'persistent_area', material: { id: 'webs', flammability: { kind: 'flammable' } },
    });
    expect(grease?.operation).toMatchObject({
      kind: 'persistent_area', material: {
        id: 'grease', flammability: { kind: 'optional_rule', rule: 'flammable_grease' },
      },
    });
  });

  it('ignition_ignores_exposure: fire ignites the exact exposed cube but not an unexposed neighbor', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    const web = state.persistentAreas[0];
    if (web === undefined) throw new Error('Web area was not created.');
    const exposed = state.tokens.find((token) => token.combatantId === subject.target.id)?.position;
    if (exposed === undefined) throw new Error('Target token was not placed.');
    const neighbor = { column: exposed.column + 1, row: exposed.row };
    expect(persistentAreaContains(web, neighbor, null, state)).toBe(true);
    expect(web.burningCells.map((entry) => entry.cell)).toEqual([exposed]);
    expect(web.burningCells.some((entry) =>
      entry.cell.column === neighbor.column && entry.cell.row === neighbor.row)).toBe(false);

    state = reduceEncounter(state, { type: 'end_turn', actor: subject.fireDealer.id }, faceOne).state;
    expect(state.persistentAreas[0]?.burningCells.map((entry) => entry.cell)).toEqual([exposed]);
  });

  it('cold_ignites: non-fire damage in the same cell does not ignite while Fire damage does', () => {
    const run = (type: 'Cold' | 'Fire'): EncounterState => {
      const subject = setup();
      let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
      state = advanceToFireDealer(state, subject.owner);
      return dealDamage(state, subject.fireDealer, subject.target, damageType(type));
    };
    expect(run('Cold').persistentAreas[0]?.burningCells).toEqual([]);
    expect(run('Fire').persistentAreas[0]?.burningCells).toHaveLength(1);
  });

  it('same Fire event ignites flammable overlapping areas and leaves a nonflammable area unchanged', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
    state = createArea(state, area(state, WEB_MATERIAL));
    state = createArea(state, area(state, NONFLAMMABLE_MATERIAL));
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    expect(state.persistentAreas.map((candidate) => candidate.burningCells.length)).toEqual([1, 1, 0]);
  });

  it('optional-rule flag off vs on: 2024 Grease stays nonflammable unless flammable_grease is enabled', () => {
    const run = (enabled: boolean): EncounterState => {
      const subject = setup(enabled ? ['flammable_grease'] : []);
      let state = createArea(subject.state, area(subject.state, GREASE_MATERIAL));
      state = advanceToFireDealer(state, subject.owner);
      return dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    };
    expect(run(false).persistentAreas[0]?.burningCells).toEqual([]);
    expect(run(true).persistentAreas[0]?.burningCells).toHaveLength(1);
  });

  it('burning Web deals exactly 2d4 Fire damage at start of turn', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    expect(hitPoints(state, subject.target.id)).toBe(29);
    state = reduceEncounter(state, { type: 'end_turn', actor: subject.fireDealer.id }, faceOne).state;
    expect(hitPoints(state, subject.target.id)).toBe(27);
  });

  it('a banished combatant in an ignited cell takes no burning damage at start of turn', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    state = reduceEncounter(state, {
      type: 'apply_effect',
      actor: subject.fireDealer.id,
      cost: 'none',
      effect: {
        targets: [subject.target.id],
        duration: { kind: 'permanent' },
        concentration: false,
        stackingIdentity: effectStackingIdentity('test:burning-cell-banishment'),
        stacking: 'replace_same_source',
        repeatedSave: null,
        payload: {
          kind: 'temporary_banishment',
          returnDamage: {
            terms: [{
              type: damageType('Force'),
              dice: { count: 0, sides: dieSides(4), modifier: 0 },
            }],
            critical: false,
            responses: [],
          },
          returnPlacement: 'previous_or_nearest_unoccupied',
        },
      },
    }, faceOne).state;
    const banishedHitPoints = hitPoints(state, subject.target.id);
    expect(state.tokens.some((token) => token.combatantId === subject.target.id)).toBe(false);

    expect(() => {
      state = reduceEncounter(
        state,
        { type: 'end_turn', actor: subject.fireDealer.id },
        faceOne,
      ).state;
    }).not.toThrow();
    expect(hitPoints(state, subject.target.id)).toBe(banishedHitPoints);
  });

  it('burn_lingers: an ignited cube burns away after exactly one full round', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL));
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    const exposed = state.persistentAreas[0]?.burningCells[0]?.cell;
    if (exposed === undefined) throw new Error('Web cube did not ignite.');

    state = reduceEncounter(state, { type: 'end_turn', actor: subject.fireDealer.id }, faceOne).state;
    state = reduceEncounter(state, { type: 'end_turn', actor: subject.target.id }, faceOne).state;
    expect(state.persistentAreas[0]?.burningCells).toHaveLength(1);
    expect(state.persistentAreas[0]?.burnedAwayCells).toEqual([]);

    state = reduceEncounter(state, { type: 'end_turn', actor: subject.owner.id }, faceOne).state;
    expect(state.persistentAreas[0]?.burningCells).toEqual([]);
    expect(state.persistentAreas[0]?.burnedAwayCells).toEqual([exposed]);
  });

  it('restraint_survives_burn: Web restraint ends when its burned cube burns away', () => {
    const subject = setup();
    let state = createArea(subject.state, area(subject.state, WEB_MATERIAL, webHooks()));
    expect(combatantConditions(state, subject.target.id).map((condition) => condition.name)).toContain('Restrained');
    state = advanceToFireDealer(state, subject.owner);
    state = dealDamage(state, subject.fireDealer, subject.target, damageType('Fire'));
    state = reduceEncounter(state, { type: 'end_turn', actor: subject.fireDealer.id }, faceOne).state;
    state = reduceEncounter(state, { type: 'end_turn', actor: subject.target.id }, faceOne).state;
    expect(combatantConditions(state, subject.target.id).map((condition) => condition.name)).toContain('Restrained');

    state = reduceEncounter(state, { type: 'end_turn', actor: subject.owner.id }, faceOne).state;
    expect(combatantConditions(state, subject.target.id).map((condition) => condition.name)).not.toContain('Restrained');
  });
});

tests/unit/tools/generate-arena-basis.te.source:
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { describe, expect, it } from 'vitest';
import { canonicalJson } from '../../../src/commands/canonical-json';
import { generateRoom } from '../../../src/vtt/room-generator';
import {
  generateArenaBasis,
  parseBasisGenerationArgs,
} from '../../../tools/generate-arena-basis';
import { mkdtempSync, readFileSync } from '../../helpers/test-filesystem';

describe('arena basis generator', () => {
  it('parses the explicit difficulty profile and writes deterministic canonical rooms', async () => {
    const outPath = mkdtempSync(join(tmpdir(), 'dnd-hard-basis-generator-'));
    const config = parseBasisGenerationArgs([
      '--difficulty', 'hard',
      '--seed', '5117001',
      '--rooms', '2',
      '--out', outPath,
    ]);

    expect(config).toEqual({
      difficulty: 'hard',
      seed: 5_117_001,
      rooms: 2,
      outPath,
    });
    await generateArenaBasis(config);

    for (const seed of [5_117_001, 5_117_002]) {
      expect(readFileSync(join(outPath, `seed-${String(seed)}.json`), 'utf8')).toBe(
        `${canonicalJson(generateRoom(seed, { difficulty: 'hard' }))}\n`,
      );
    }
  });

  it('rejects unknown difficulty profiles before writing', () => {
    expect(() => parseBasisGenerationArgs([
      '--difficulty', 'nightmare',
      '--seed', '5117001',
      '--rooms', '12',
      '--out', tmpdir(),
    ])).toThrow('--difficulty must be standard, hard, or brutal.');
  });

  it('accepts the brutal difficulty profile', () => {
    const outPath = mkdtempSync(join(tmpdir(), 'dnd-brutal-basis-generator-'));
    expect(parseBasisGenerationArgs([
      '--difficulty', 'brutal',
      '--seed', '6203001',
      '--rooms', '3',
      '--out', outPath,
    ])).toEqual({ difficulty: 'brutal', seed: 6_203_001, rooms: 3, outPath });
  });
});

tests/unit/bridge/js-turn-program.test.t.source:
import { describe, expect, it } from 'vitest';
import { createEncounter, type EncounterState } from '../../../src/combat/encounter';
import { dmVisibleEncounter, projectDmView, type DmVisibleEncounterState } from '../../../src/combat/visibility';
import { combatantId } from '../../../src/combat/values';
import {
  JS_TURN_PROGRAM_CANONICAL_EXAMPLE,
  JsTurnProgramBudgetError,
  JsTurnProgramSyntaxError,
  interpretJsTurnProgram,
  parseJsTurnProgram,
} from '../../../src/vtt/dm-bridge/js-turn-program';
import { monsterProfile, placedToken, playerProfile } from '../combat/fixtures';

function projection(): DmVisibleEncounterState {
  const monsterA = monsterProfile('js-program-a', { hitPoints: 40 });
  const monsterB = monsterProfile('js-program-b', { hitPoints: 30 });
  const playerA = playerProfile('js-program-player-a');
  const playerB = playerProfile('js-program-player-b');
  const base = createEncounter({
    bounds: { columns: 12, rows: 3 },
    combatants: [monsterA, monsterB, playerB, playerA],
    tokens: [
      placedToken(monsterA, 0),
      placedToken(monsterB, 1),
      placedToken(playerB, 3),
      placedToken(playerA, 3, 1),
    ],
  });
  const state: EncounterState = { ...base, activeCombatant: monsterA.id };
  return dmVisibleEncounter(projectDmView(state));
}

const ACTOR = combatantId('combatant:js-program-a');

describe('restricted JS turn-program parser and interpreter', () => {
  it('parses the typed grammar: const, arithmetic, comparisons, logic, arrays, objects, calls, if/else, and API-array for-of', () => {
    const source = `
      const radius = (2 + 4) * 5;
      const flags = [true, false, null];
      const note = {label: "deterministic", radius: radius};
      for (const ally of alliesWithin(radius)) {
        const allyHealthy = hpPercent(ally) >= 50 && distanceTo(ally) <= radius;
      }
      const target = lowestHp(enemiesWithin(radius));
      if (target !== null && !(1 > 2)) {
        emit(priority([attack(target), forceSave(target), move(target), retreat(1, 2), dash(), disengage(), dodge(), endTurn()]));
      } else {
        emit(endTurn());
      }
    `;

    const ast = parseJsTurnProgram(source);
    const result = interpretJsTurnProgram(source, projection(), ACTOR);

    expect(ast.kind).toBe('program');
    expect(ast.statements.map((statement) => statement.kind)).toEqual([
      'const', 'const', 'const', 'for_of', 'const', 'if',
    ]);
    expect(result.emittedDecisionProgram).toMatchObject({
      kind: 'priority',
      choices: [
        { kind: 'action', action: { kind: 'attack', target: { combatantId: 'combatant:js-program-player-a' } } },
        { kind: 'action', action: { kind: 'force_save' } },
        { kind: 'action', action: { kind: 'move_toward' } },
        { kind: 'action', action: { kind: 'retreat_toward' } },
        { kind: 'action', action: { action: 'dash' } },
        { kind: 'action', action: { action: 'disengage' } },
        { kind: 'action', action: { action: 'dodge' } },
        { kind: 'action', action: { action: 'end_turn' } },
      ],
    });
    expect(result.steps).toBeGreaterThan(30);
  });

  it.each([
    ['while loop', 'while (true) {}', 'Forbidden construct "while loop" at line 1, column 1.'],
    ['function declaration', 'function choose() {}', 'Forbidden construct "function declaration" at line 1, column 1.'],
    ['this', 'emit(this);', 'Forbidden construct "this" at line 1, column 6.'],
    ['class declaration', 'class Plan {}', 'Forbidden construct "class declaration" at line 1, column 1.'],
    ['prototype access', 'const x = prototype;', 'Forbidden prototype property "prototype" at line 1, column 11.'],
    ['prototype literal', 'const x = {__proto__: 1};', 'Forbidden prototype property "__proto__" at line 1, column 12.'],
    ['ambient global', 'emit(globalThis);', 'Forbidden global "globalThis" at line 1, column 6.'],
    ['import', 'import x from "x";', 'Forbidden construct "import" at line 1, column 1.'],
    ['try', 'try {} catch (error) {}', 'Forbidden construct "try statement" at line 1, column 1.'],
    ['regular expression', 'const x = /attack/;', 'Forbidden construct "regular expression" at line 1, column 11.'],
    ['Date', 'emit(Date);', 'Forbidden global "Date" at line 1, column 6.'],
    ['Math.random', 'emit(Math.random());', 'Forbidden global "Math" at line 1, column 6.'],
    ['member access', 'const target = nearestEnemy(); emit(target.id);', 'Member access is forbidden at line 1, column 43.'],
    ['assignment', 'const target = nearestEnemy(); target = null;', 'Assignment is forbidden at line 1, column 39.'],
    ['arrow function', 'const f = () => 1;', 'Forbidden construct "arrow function" at line 1, column 14.'],
  ])('rejects forbidden %s with a precise source error', (_name, source, message) => {
    expect(() => parseJsTurnProgram(source)).toThrowError(new JsTurnProgramSyntaxError(message));
  });

  it('rejects for-of over a locally constructed array rather than an API-returned array', () => {
    expect(() => parseJsTurnProgram('const xs = []; for (const x of xs) { emit(endTurn()); }')).toThrow(
      'For-of accepts only alliesWithin(...) or enemiesWithin(...)',
    );
  });

  it('rejects an object literal that tries to impersonate a typed API DecisionProgram', () => {
    const source = 'emit({kind: "action", action: {kind: "use_action", action: "end_turn"}});';
    expect(() => interpretJsTurnProgram(source, projection(), ACTOR)).toThrow(
      'emit requires a DecisionProgram.',
    );
  });

  it('forbidden_construct_executes rejects while before an executable AST exists', () => {
    expect(() => interpretJsTurnProgram('while (true) { emit(endTurn()); }', projection(), ACTOR)).toThrow(
      'Forbidden construct "while loop"',
    );
  });

  it('step_budget_ignored stops a costly API-array loop at the exact configured bound', () => {
    const source = `
      for (const enemy of enemiesWithin(100)) {
        const hp = hpPercent(enemy);
      }
      emit(endTurn());
    `;
    expect(() => interpretJsTurnProgram(source, projection(), ACTOR, { stepBudget: 5 })).toThrowError(
      new JsTurnProgramBudgetError('JS turn-program exceeded step budget 5.'),
    );
  });

  it('enforces the wall-clock budget through an injected monotonic clock', () => {
    let now = 0;
    expect(() => interpretJsTurnProgram('emit(endTurn());', projection(), ACTOR, {
      timeBudgetMs: 2,
      now: () => {
        now += 2;
        return now;
      },
    })).toThrowError(new JsTurnProgramBudgetError('JS turn-program exceeded time budget 2ms.'));
  });

  it('same source and projection emit an identical DecisionProgram', () => {
    const first = interpretJsTurnProgram(JS_TURN_PROGRAM_CANONICAL_EXAMPLE, projection(), ACTOR);
    const second = interpretJsTurnProgram(JS_TURN_PROGRAM_CANONICAL_EXAMPLE, projection(), ACTOR);
    expect(JSON.stringify(first.emittedDecisionProgram)).toBe(JSON.stringify(second.emittedDecisionProgram));
  });

  it('projection_order_changes_query uses combatant id as the stable equidistant tie-break', () => {
    const result = interpretJsTurnProgram('const target = nearestEnemy(); emit(attack(target));', projection(), ACTOR);
    expect(result.emittedDecisionProgram).toMatchObject({
      action: { target: { combatantId: 'combatant:js-program-player-a' } },
    });
  });

  it('emits explicit selectable programs for granted Bonus Action attacks and Action Surge', () => {
    const result = interpretJsTurnProgram(
      'const target = nearestEnemy(); emit(priority(bonusAttack(target), actionSurge(), attack(target)));',
      projection(),
      ACTOR,
    );
    expect(result.emittedDecisionProgram).toEqual({
      kind: 'priority',
      choices: [
        {
          kind: 'action',
          action: {
            kind: 'bonus_attack',
            target: { kind: 'combatant', combatantId: 'combatant:js-program-player-a' },
          },
        },
        { kind: 'action', action: { kind: 'use_action', action: 'action_surge' } },
        {
          kind: 'action',
          action: {
            kind: 'attack',
            target: { kind: 'combatant', combatantId: 'combatant:js-program-player-a' },
          },
        },
      ],
    });
  });
});

tests/unit/combat/initiative-modes.test..source:
import { describe, expect, it } from 'vitest';
import {
  AlgorithmController,
  ControllerRegistry,
  type StandingReactionPolicy,
} from '../../../src/combat/controllers';
import { TurnCoordinator } from '../../../src/combat/coordinator';
import {
  createEncounter,
  type EncounterState,
  type InitiativeMode,
} from '../../../src/combat/encounter';
import type { EncounterCommand } from '../../../src/combat/events';
import { damageType, dieSides, type CombatantId } from '../../../src/combat/values';
import { monsterProfile, placedToken, playerProfile } from './fixtures';

function sequenceRng(values: readonly number[]): () => number {
  let index = 0;
  return () => {
    const value = values[index];
    if (value === undefined) throw new Error('Initiative fixture exhausted its RNG values.');
    index += 1;
    return value;
  };
}

function modeFixture(mode?: InitiativeMode): {
  readonly state: EncounterState;
  readonly ids: Readonly<Record<'pcFast' | 'pcSlow' | 'monsterFast' | 'monsterMid' | 'monsterSlow', CombatantId>>;
} {
  const pcFast = playerProfile('mode-pc-fast', { initiativeBonus: 0 });
  const monsterSlow = monsterProfile('mode-monster-slow', { initiativeBonus: 1 });
  const pcSlow = playerProfile('mode-pc-slow', { initiativeBonus: 0 });
  const monsterFast = monsterProfile('mode-monster-fast', { initiativeBonus: 3 });
  const monsterMid = monsterProfile('mode-monster-mid', { initiativeBonus: 2 });
  const combatants = [pcFast, monsterSlow, pcSlow, monsterFast, monsterMid];
  return {
    state: createEncounter({
      ...(mode === undefined ? {} : { config: { initiativeMode: mode } }),
      bounds: { columns: 12, rows: 2 },
      combatants,
      tokens: combatants.map((profile, index) => placedToken(profile, index * 2)),
    }),
    ids: {
      pcFast: pcFast.id,
      pcSlow: pcSlow.id,
      monsterFast: monsterFast.id,
      monsterMid: monsterMid.id,
      monsterSlow: monsterSlow.id,
    },
  };
}

async function firstRoundOrder(
  mode: InitiativeMode,
): Promise<{ readonly order: readonly CombatantId[]; readonly state: EncounterState }> {
  const fixture = modeFixture(mode);
  const registry = new ControllerRegistry(fixture.state.combatants.map((subject) => ({
    combatantId: subject.profile.id,
    controller: new AlgorithmController(),
  })));
  const coordinator = new TurnCoordinator(
    fixture.state,
    registry,
    sequenceRng([0.9, 0.7, 0.6, 0.4, 0.2]),
  );
  const rolled = await coordinator.step();
  if (rolled.kind !== 'applied') throw new Error(rolled.reason);
  while (
    coordinator.state().eventLog.filter(
      (event) => event.type === 'turn_started' && event.round === 1,
    ).length < fixture.state.combatants.length
  ) {
    const result = await coordinator.step();
    if (result.kind !== 'applied') throw new Error(result.reason);
  }
  return {
    order: coordinator.state().eventLog.flatMap((event) =>
      event.type === 'turn_started' && event.round === 1 ? [event.combatant] : []),
    state: coordinator.state(),
  };
}

describe('typed encounter initiative modes', () => {
  it('defaults new encounters to the owner-ruled shared enemy block', () => {
    expect(modeFixture().state.config).toEqual({ initiativeMode: 'shared_enemy' });
  });

  it.each([
    [
      'per_combatant',
      ['pcFast', 'monsterSlow', 'pcSlow', 'monsterFast', 'monsterMid'],
    ],
    [
      'shared_enemy',
      ['pcFast', 'monsterFast', 'monsterMid', 'monsterSlow', 'pcSlow'],
    ],
    [
      'side_alternating',
      ['pcFast', 'pcSlow', 'monsterFast', 'monsterMid', 'monsterSlow'],
    ],
  ] as const)('pins the complete first-round order for %s', async (mode, names) => {
    const fixture = modeFixture(mode);
    const result = await firstRoundOrder(mode);
    expect(result.order).toEqual(names.map((name) => fixture.ids[name]));
  });

  it('shared_block_splits keeps every enemy activation in one initiative slot', async () => {
    const fixture = modeFixture('shared_enemy');
    const result = await firstRoundOrder('shared_enemy');
    const monsterIds = [
      fixture.ids.monsterFast,
      fixture.ids.monsterMid,
      fixture.ids.monsterSlow,
    ];
    const monsterIndexes = monsterIds.map((id) => result.order.indexOf(id));
    expect(monsterIndexes).toEqual([1, 2, 3]);
    expect(new Set(
      result.state.initiative
        .filter((entry) => monsterIds.includes(entry.combatant))
        .map((entry) => entry.slot),
    ).size).toBe(1);
    const ordered = result.state.eventLog.find((event) => event.type === 'initiative_ordered');
    expect(ordered).toMatchObject({ slots: expect.arrayContaining([monsterIds]) });
  });

  it('block_order_nondeterministic keeps within-block ordering stable across replay seeds', async () => {
    const orders = await Promise.all([
      firstRoundOrder('shared_enemy'),
      (async () => {
        const fixture = modeFixture('shared_enemy');
        const registry = new ControllerRegistry(fixture.state.combatants.map((subject) => ({
          combatantId: subject.profile.id,
          controller: new AlgorithmController(),
        })));
        const coordinator = new TurnCoordinator(
          fixture.state,
          registry,
          sequenceRng([0.05, 0.95, 0.15, 0.4]),
        );
        await coordinator.step();
        return { state: coordinator.state() };
      })(),
    ]);
    const withinBlock = (state: EncounterState): readonly CombatantId[] => {
      const block = state.eventLog.find((event) => event.type === 'initiative_block_rolled');
      if (block === undefined || block.type !== 'initiative_block_rolled') {
        throw new Error('Shared encounter did not emit its block roll.');
      }
      return block.combatants;
    };
    expect(withinBlock(orders[0].state)).toEqual(withinBlock(orders[1].state));
  });

  it('allows a PC Opportunity Attack to interrupt movement inside the shared enemy block', async () => {
    const mover = monsterProfile('block-mover', { initiativeBonus: 20, hitPoints: 20 });
    const nextMonster = monsterProfile('block-next', { initiativeBonus: 10 });
    const reactor = playerProfile('block-reactor', { initiativeBonus: -20 });
    const state = createEncounter({
      config: { initiativeMode: 'shared_enemy' },
      bounds: { columns: 8, rows: 2 },
      combatants: [mover, nextMonster, reactor],
      tokens: [placedToken(mover, 1), placedToken(nextMonster, 5), placedToken(reactor, 0)],
    });
    const registry = new ControllerRegistry(state.combatants.map((subject) => ({
      combatantId: subject.profile.id,
      controller: new AlgorithmController(),
    })));
    const move: Extract<EncounterCommand, { readonly type: 'move' }> = {
      type: 'move',
      actor: mover.id,
      path: [{ column: 2, row: 0 }],
      cause: 'voluntary',
    };
    const opportunityAttack: Extract<EncounterCommand, { readonly type: 'opportunity_attack' }> = {
      type: 'opportunity_attack',
      actor: reactor.id,
      target: mover.id,
      attackBonus: 100,
      criticalFloor: 20,
      rollMode: 'normal',
      attackerCanSeeTarget: true,
      targetCanSeeAttacker: true,
      damage: {
        terms: [{
          type: damageType('Force'),
          dice: { count: 0, sides: dieSides(6), modifier: 1 },
        }],
        critical: false,
        responses: [],
      },
    };
    const policies = new Map<CombatantId, StandingReactionPolicy>([
      [reactor.id, { opportunityAttack: 'use' }],
    ]);
    const coordinator = new TurnCoordinator(state, registry, sequenceRng([0.1, 0.9, 0.5]), {
      turnLegalActions: (current, actor) => ({
        actions: actor === mover.id && current.combatants.find(
          (subject) => subject.profile.id === mover.id,
        )?.turn.movement.spent === 0
          ? [move]
          : [{ type: 'end_turn', actor }],
      }),
      reactionLegalActions: () => [opportunityAttack],
      standingReactionPolicies: policies,
    });

    await coordinator.step();
    const movement = await coordinator.step();
    if (movement.kind !== 'applied') throw new Error(movement.reason);
    expect(movement.events.map((event) => event.type)).toEqual([
      'resource_spent',
      'damage_applied',
      'attack_resolved',
      'movement_completed',
    ]);
    await coordinator.step();
    expect(coordinator.state().activeCombatant).toBe(nextMonster.id);
    const firstRoundStarts = coordinator.state().eventLog.flatMap((event) =>
      event.type === 'turn_started' && event.round === 1 ? [event.combatant] : []);
    expect(firstRoundStarts).toEqual([mover.id, nextMonster.id]);
  });
});

